$ErrorActionPreference='Stop'
Set-Location $PSScriptRoot
$dir=Join-Path $PWD 'artifacts\glass21-640'
foreach($file in @('validation-result.json','release-result.json','deployment-result.json','installed-ui-result.json','installed-system-dock.png','installed-power.png','installed-overview.png')){
 if(!(Test-Path (Join-Path $dir $file))){throw "Missing evidence $file"}
}
$deploy=Get-Content (Join-Path $dir 'deployment-result.json') -Raw|ConvertFrom-Json
$ui=Get-Content (Join-Path $dir 'installed-ui-result.json') -Raw|ConvertFrom-Json
if($deploy.installedVersion -ne '15.4.640' -or !$deploy.healthy -or !$deploy.hidOk -or !$deploy.payloadVerified){throw 'Deployment verification incomplete'}
if($ui.version -ne '15.4.640' -or !$ui.discardVerified -or $ui.pendingState -eq $ui.beforeState){throw 'Installed native toggle proof incomplete'}
$installers=@(Get-ChildItem ([Environment]::GetFolderPath('Desktop')) -Filter 'Spankyho_Optimizer_V*_Setup*.exe' -File)
if($installers.Count -ne 1 -or $installers[0].Name -ne 'Spankyho_Optimizer_V15_4_640_Setup_Compact.exe'){throw 'Desktop installer invariant failed'}
$m=[IO.File]::ReadAllText((Join-Path $PWD 'glass21-639-measure.ps1')).Replace('artifacts\glass21-639','artifacts\glass21-640')
[IO.File]::WriteAllText((Join-Path $PWD 'glass21-640-measure.ps1'),$m)
& .\glass21-640-measure.ps1 -Label installed
if(!$?){throw 'Installed performance verification failed'}
$a=Join-Path $PWD 'AGENTS.md'
$s=[IO.File]::ReadAllText($a).Replace('- Current UI: deep black surfaces, restrained blue controls, colored hardware pictures/icons; app-update Settings block removed.','- Current UI: approved Glass21 native desktop blur and translucent dark panels, blue pill controls and native switch state lifecycle; System/Privacy groups have no decorative icons. Overview black hardware/header and original colored hardware navigation assets preserved. App-update Settings block remains removed. Design: docs/superpowers/plans/Glass21-design.md; final tested/released/installed15.4.640.')
[IO.File]::WriteAllText($a,$s)
[IO.File]::WriteAllText((Join-Path $dir 'final-summary.md'),'Approved Glass21 implemented and installed15.4.640. Native desktop acrylic, glass navigation/panels/actions, responsive System/Privacy groups without icons, real catalog/policy/pending/readback, original Overview hardware preserved. Final native switch proves ON to OFF and Discard restoration without Windows Apply. Fresh full build-test and six UI suites pass; release gate and installer transaction suites pass; installed payload hash and fresh fan agent/HID pass. Screens from installed compositor. No pending implementation task. Source641 is only automatic next-version bump and untested. Native acrylic follows Windows policy; it approximates the visual direction rather than claiming Apple refraction. No new heavy animations. Existing cache lifecycle kept and regression-tested; narrow layout follows column order. Hardware fallback/high contrast appearance uses native policy and was not globally toggled on user PC. Native switch retains standard automation/focus. Initial compile mismatches, bootstrap resource miss, custom toggle visual defect, preview file lock and obscured capture were corrected and final evidence replaces failed attempts.')
& .\ai-workflow.ps1 -Action complete-task -TaskId glass21-639 -Summary 'Approved Glass21 implemented, tested/released/installed15.4.640: native desktop blur, glass panels/blue controls, responsive no-icon System/Privacy groups; original Overview/hardware preserved. Native ON/OFF pending and Discard proven; installer/fan/HID verified.' -NextAction 'No pending implementation. Continue only from approved Glass21 spec and actual640 screenshots if user requests refinements; source641 auto bump is untested.' -Done @('Approved Glass21 implemented across shared section chrome','Native switch state corrected','Full fresh build-test and six UI suites','Gated release640 installed; one Desktop EXE','Fresh fan agent/HID and payload hash verified','Actual installed System/Power/Overview screenshots','Native pending OFF and Discard without applying Windows changes') -Pending @() -FilesTouched @('AGENTS.md','src\SpankyhoOptimizer\MainWindow.Glass21.cs','src\SpankyhoOptimizer\MainWindow.Shell.cs','src\SpankyhoOptimizer\MainWindow.Theme.cs','src\SpankyhoOptimizer\MainWindow.NeutralUi.cs','src\SpankyhoOptimizer\MainWindow.MaterialButtons.cs','src\SpankyhoOptimizer\MainWindow.TweakVirtualization.cs','src\SpankyhoOptimizer\MainWindow.ServicePrewarm.cs','src\SpankyhoOptimizer\MainWindow.cs','src\SpankyhoOptimizer\App.xaml','src\SpankyhoOptimizer\MainWindow.VisualQa.cs') -Evidence @('artifacts\glass21-640\validation-result.json','artifacts\glass21-640\release-result.json','artifacts\glass21-640\deployment-result.json','artifacts\glass21-640\installed-ui-result.json','artifacts\glass21-640\installed-performance.json','artifacts\glass21-640\installed-system-dock.png','artifacts\glass21-640\installed-power.png','artifacts\glass21-640\installed-overview.png','artifacts\glass21-640\final-summary.md','docs\superpowers\plans\Glass21-design.md','artifacts\glass21-639\review.txt') -RefreshIndex
Write-Output 'GLASS21_FINAL640_COMPLETE'
